-- Proposals generated by the configurator (AI or rules-based) and the log used for rate limiting.
-- All access goes through server routes using the service role key; RLS is enabled with no public policies.

create table public.proposals (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  payload jsonb not null,
  source text not null check (source in ('ai', 'rules')),
  created_at timestamptz not null default now()
);

create table public.generation_log (
  id uuid primary key default gen_random_uuid(),
  ip_hash text not null,
  email_hash text,
  provider text not null,
  ok boolean not null,
  created_at timestamptz not null default now()
);

alter table public.proposals enable row level security;
alter table public.generation_log enable row level security;

-- Lookups for "generations in the last 24 hours" per IP and per email.
create index generation_log_ip_hash_created_at_idx
  on public.generation_log (ip_hash, created_at desc);

create index generation_log_email_hash_created_at_idx
  on public.generation_log (email_hash, created_at desc)
  where email_hash is not null;
